package com.example.starter;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.Bean;

import java.time.Clock;

/**
 * 业务题目工程入口；当前仅提供 Web 服务及数据库健康检查，不包含题目业务实现。
 */
@SpringBootApplication
public class StarterApplication {

    /**
     * 使用外部提供的数据库连接配置启动服务。
     */
    public static void main(String[] args) {
        SpringApplication.run(StarterApplication.class, args);
    }

    /**
     * 业务时钟：暂停/恢复记录使用 UTC 时刻，测试可替换为可控时钟。
     */
    @Bean
    public Clock businessClock() {
        return Clock.systemUTC();
    }
}

package com.example.starter.firmware.domain;

/**
 * 设备投放任务，同设备同发布单最多一条。
 *
 * @param id          任务ID
 * @param releaseId   所属发布单ID
 * @param deviceId    设备ID
 * @param status      任务状态
 * @param firstResult 首次回执结果（SUCCESS/FAILED），未回执为 null
 */
public record RolloutTask(long id, long releaseId, String deviceId, TaskStatus status,
                          ReceiptResult firstResult) {
}

package com.example.starter.firmware.domain;

/**
 * 设备登记信息。
 *
 * @param deviceId       设备唯一标识
 * @param model          设备型号，登记后不可修改
 * @param currentVersion 设备当前固件版本
 * @param bucketNo       灰度分桶号，取值0~99，登记后不可修改
 */
public record Device(String deviceId, String model, String currentVersion, int bucketNo) {
}

package com.example.starter.firmware.domain;

/**
 * 发布单自动暂停记录，每个监控轮次至多一条，历史不可改。
 *
 * @param id            暂停记录ID
 * @param releaseId     所属发布单ID
 * @param monitorRound  触发暂停的监控轮次
 * @param triggerTaskId 触发暂停的回执任务ID
 * @param successCount  暂停时刻本轮成功样本数
 * @param failedCount   暂停时刻本轮失败样本数
 * @param pausedAtUtc   暂停时刻，UTC，ISO-8601 格式
 */
public record PauseRecord(long id, long releaseId, int monitorRound, long triggerTaskId,
                          int successCount, int failedCount, String pausedAtUtc) {
}

