package com.example.starter.firmware.domain;

/**
 * 回执结果：SUCCESS 成功（更新设备当前版本）；FAILED 失败（本轮不再投放）。
 */
public enum ReceiptResult {
    SUCCESS,
    FAILED
}

package com.example.starter.firmware.domain;

/**
 * 发布单状态：ACTIVE 投放中；PAUSED 失败率自动暂停（可人工恢复）；CANCELLED 已取消（终态）。
 */
public enum ReleaseStatus {
    ACTIVE,
    PAUSED,
    CANCELLED
}

package com.example.starter.firmware.domain;

/**
 * 投放任务状态：PENDING 待回执；SUCCESS 成功；FAILED 失败；CANCELLED 已取消。
 */
public enum TaskStatus {
    PENDING,
    SUCCESS,
    FAILED,
    CANCELLED
}

package com.example.starter.firmware.domain;

/**
 * 发布单人工恢复记录，历史不可改。
 *
 * @param id           恢复记录ID
 * @param releaseId    所属发布单ID
 * @param newRound     本次恢复开启的新监控轮次
 * @param reason       人工恢复原因
 * @param resumedAtUtc 恢复时刻，UTC，ISO-8601 格式
 */
public record ResumeRecord(long id, long releaseId, int newRound, String reason, String resumedAtUtc) {
}

